def test_roundtrip_json_wordrenderresult():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "stats": {
        "headings": 1,
        "paragraphs": 1,
        "codeBlocks": 1,
        "blockQuotes": 1,
        "lists": 1,
        "listItems": 1,
        "tables": 1,
        "links": 1,
        "thematicBreaks": 1,
        "warnings": []
      },
      "manifest": {
        "kind": "sample",
        "parts": [],
        "relationships": [],
        "contentTypes": []
      },
      "invariants": {
        "allRelationshipIdsResolve": true,
        "allContentTypesDeclared": true,
        "noDuplicateRelationshipIds": true,
        "allMediaPartsReachable": true,
        "noOrphanRequiredParts": true,
        "allHyperlinksHaveRelationships": true,
        "allAnchorLinksHaveBookmarks": true,
        "allNumberingReferencesDefined": true,
        "allTableHeadersMarked": true
      },
      "warnings": []
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = WordRenderResult.load(original_data)
    saved_data = instance.save()
    reloaded = WordRenderResult.load(saved_data)
    assert reloaded is not None


